def make(n):
    markers = []
    for i in range(n):
        # a simple but valid marker expression
        markers.append([f'python_version >= "3.{i%10}"'])
    return markers

def make(n):
    # Build a marker like: python_version >= '3.7' and (python_version >= '3.8' and (...))
    inner = "python_version >= '3.7'"
    for i in range(n):
        inner = f"python_version >= '3.{7+i}' and ({inner})"
    return [[inner]]
